CREATE TABLE IF NOT EXISTS subject (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,code TEXT,color TEXT NOT NULL DEFAULT '#5B5BD6',credits REAL,exam_weight REAL DEFAULT 100,archived INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS unit (id INTEGER PRIMARY KEY AUTOINCREMENT,subject_id INTEGER NOT NULL REFERENCES subject(id) ON DELETE CASCADE,name TEXT NOT NULL,order_index INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS topic (id INTEGER PRIMARY KEY AUTOINCREMENT,unit_id INTEGER NOT NULL REFERENCES unit(id) ON DELETE CASCADE,name TEXT NOT NULL,difficulty INTEGER DEFAULT 3,marks REAL DEFAULT 0,est_minutes INTEGER DEFAULT 60,status TEXT DEFAULT 'not_started',confidence REAL DEFAULT 1.0,source_ref TEXT,notes TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS prereq (topic_id INTEGER NOT NULL REFERENCES topic(id) ON DELETE CASCADE,prereq_topic_id INTEGER NOT NULL REFERENCES topic(id) ON DELETE CASCADE,PRIMARY KEY(topic_id,prereq_topic_id));
CREATE TABLE IF NOT EXISTS task (id INTEGER PRIMARY KEY AUTOINCREMENT,topic_id INTEGER REFERENCES topic(id) ON DELETE SET NULL,subject_id INTEGER NOT NULL REFERENCES subject(id) ON DELETE CASCADE,type TEXT NOT NULL,title TEXT NOT NULL,est_minutes INTEGER NOT NULL DEFAULT 30,actual_minutes INTEGER DEFAULT 0,due_date TEXT,scheduled_date TEXT,priority_score REAL DEFAULT 0,status TEXT DEFAULT 'pending',is_revision INTEGER DEFAULT 0,created_by TEXT DEFAULT 'ai',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS exam (id INTEGER PRIMARY KEY AUTOINCREMENT,subject_id INTEGER NOT NULL REFERENCES subject(id) ON DELETE CASCADE,exam_date TEXT NOT NULL,exam_type TEXT DEFAULT 'final',weightage REAL DEFAULT 100,scope_unit_ids TEXT DEFAULT '[]',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS blackout (id INTEGER PRIMARY KEY AUTOINCREMENT,date TEXT NOT NULL UNIQUE,reason TEXT);
CREATE TABLE IF NOT EXISTS review_item (id INTEGER PRIMARY KEY AUTOINCREMENT,topic_id INTEGER NOT NULL REFERENCES topic(id) ON DELETE CASCADE,ease REAL DEFAULT 2.5,interval_days INTEGER DEFAULT 1,next_review TEXT NOT NULL,reps INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS task_session (id INTEGER PRIMARY KEY AUTOINCREMENT,task_id INTEGER REFERENCES task(id) ON DELETE CASCADE,started_at TEXT NOT NULL,ended_at TEXT,minutes INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS xp_event (id INTEGER PRIMARY KEY AUTOINCREMENT,amount INTEGER NOT NULL,reason TEXT NOT NULL,ref_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS badge (key TEXT PRIMARY KEY,earned_at TEXT);
CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK(id=1),daily_capacity_minutes INTEGER DEFAULT 120,study_days TEXT DEFAULT '[1,2,3,4,5,6,0]',buffer_pct INTEGER DEFAULT 15,theme TEXT DEFAULT 'auto',ai_provider TEXT DEFAULT '',web_lock_key TEXT DEFAULT '',daily_goal INTEGER DEFAULT 3,weekly_goal INTEGER DEFAULT 5,first_task_date TEXT);
INSERT OR IGNORE INTO settings(id) VALUES(1);
